    <script>const clock = document.getElementById('check-in-clock'); const timezone = @json(config('app.timezone')); const refreshClock = () => { clock.textContent = new Intl.DateTimeFormat('en-US', { timeZone: timezone, month: 'short', day: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date()).replace(',', ' •'); }; refreshClock(); setInterval(refreshClock, 30000);</script>
